// /sites — generated by `pnpm gen:screen sites`, then built: every project/site the user may see, each
// opening its Site page (E1, E5). Strings are i18n keys; data from org.client.list / org.site.list.
import { useEffect, useState } from 'react';
import { Link } from '@tanstack/react-router';
import { Card, FormMessage, PageHeader, useI18n } from '@ocs/ui';
import { loadPortfolio, type ClientSummary, type SiteSummary } from '../api.ts';

type State =
  | { kind: 'loading' }
  | { kind: 'failed' }
  | { kind: 'loaded'; clients: ClientSummary[]; sites: SiteSummary[] };

export function SitesPage() {
  const { t } = useI18n();
  const [state, setState] = useState<State>({ kind: 'loading' });

  useEffect(() => {
    loadPortfolio().then(
      (data) => {
        setState({ kind: 'loaded', ...data });
      },
      () => {
        setState({ kind: 'failed' });
      },
    );
  }, []);

  return (
    <>
      <PageHeader eyebrow={`/ ${t('sites.title')}`} title={t('sites.title')} />
      {state.kind === 'loading' ? <p>{t('common.loading')}</p> : null}
      {state.kind === 'failed' ? <FormMessage tone="error">{t('sites.failed')}</FormMessage> : null}
      {state.kind === 'loaded' ? (
        <Card>
          <table className="ocs-table">
            <thead>
              <tr>
                <th scope="col">{t('portfolio.col.projectId')}</th>
                <th scope="col">{t('portfolio.col.site')}</th>
                <th scope="col">{t('sites.col.client')}</th>
                <th scope="col">{t('portfolio.col.city')}</th>
                <th scope="col">{t('portfolio.col.standard')}</th>
              </tr>
            </thead>
            <tbody>
              {state.sites.map((site) => (
                <tr key={site.id}>
                  <td>
                    <Link to="/sites/$siteId" params={{ siteId: site.id }}>
                      {site.projectId}
                    </Link>
                  </td>
                  <td>{site.name}</td>
                  <td>{state.clients.find((c) => c.id === site.clientId)?.name ?? ''}</td>
                  <td>{site.cityName}</td>
                  <td>{site.standard}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </Card>
      ) : null}
    </>
  );
}
